const makeSet = (rows, question) => rows.map(([evidence, correct, wrongA, wrongB, hint], index) =>
  item(evidence, typeof question === "function" ? question(evidence, index) : `${question} Focus ${index + 1}: ${evidence.split(" ").slice(0, 4).join(" ").toLowerCase()}?`, correct, wrongA, wrongB, hint));

